/* Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT */
:where([data-moru-registry]) .ui-aspect-ratio {
  width: 100%;
  min-width: 0;
  position: relative;
  overflow: hidden;
}
:where([data-moru-registry]) .ui-aspect-ratio > img,
:where([data-moru-registry]) .ui-aspect-ratio > video {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { forwardRef, type HTMLAttributes } from 'react'
import { cn } from './_lib/cn'
import './controls-shared.css'
import './aspect-ratio.css'

export type AspectRatioProps = HTMLAttributes<HTMLDivElement> & { ratio?: number }

export const AspectRatio = forwardRef<HTMLDivElement, AspectRatioProps>(function AspectRatio(
  { ratio = 16 / 9, style, className, ...props },
  ref,
) {
  const safeRatio = Number.isFinite(ratio) && ratio > 0 ? ratio : 16 / 9
  return (
    <div
      {...props}
      ref={ref}
      className={cn('ui-aspect-ratio', className)}
      style={{ ...style, aspectRatio: safeRatio }}
    />
  )
})
